const SEVERITY_WORD: Record<string, Record<Language, string>> = {
  Low: { en: 'Low', hi: 'कम', mr: 'कमी', ta: 'குறைவு', te: 'తక్కువ', bn: 'কম' },
  Moderate: { en: 'Moderate', hi: 'मध्यम', mr: 'मध्यम', ta: 'மிதமானது', te: 'మధ్యస్థం', bn: 'মাঝারি' },
  High: { en: 'High', hi: 'उच्च', mr: 'जास्त', ta: 'அதிகம்', te: 'అధికం', bn: 'বেশি' },
};

/**
 * Returns a copy of a DiseaseInfo with every text field translated into
 * the given language. If the disease name isn't found in the reference
 * table (e.g. a name identified live by a vision model that isn't in our
 * curated list), the original object is returned untouched — callers
 * should treat that as "no localized detail available for this specific
 * name" rather than assume translation always succeeds.
 */
export function translateDisease(disease: DiseaseInfo, lang: Language): DiseaseInfo {
  const text = DISEASE_TEXT[disease.name]?.[lang];
  const severity = (SEVERITY_WORD[disease.severity]?.[lang] ?? disease.severity) as DiseaseInfo['severity'];
  if (!text) return { ...disease, severity };
  return {
    ...disease,
    name: text.name,
    crop: text.crop,
    symptoms: text.symptoms,
    cause: text.cause,
    treatment: text.treatment,
    prevention: text.prevention,
    severity,
  };
}

/** Looks up a disease/pest by its STABLE English name (case-insensitive) — used to enrich a vision-model-identified name with curated localized detail, when we have a matching entry. */
export function findKnownDiseaseByName(name: string): string | null {
  const lower = name.trim().toLowerCase();
  const match = Object.keys(DISEASE_TEXT).find((k) => k.toLowerCase() === lower);
  return match ?? null;
}
